SELECT COUNT(*) 
FROM test_result 
WHERE user_id = #{userId}

    AND DATE(test_time) >= #{startDate}


    AND DATE(test_time) <= #{endDate}

SELECT COUNT(*) 
FROM test_result 
WHERE user_id = #{userId} AND is_gland_face = 1

    AND DATE(test_time) >= #{startDate}


    AND DATE(test_time) <= #{endDate}

SELECT AVG(probability)
FROM test_result
WHERE user_id = #{userId}

    AND DATE(test_time) >= #{startDate}


    AND DATE(test_time) <= #{endDate}

SELECT 
    DATE(test_time) as date,
    COUNT(*) as total,
    SUM(CASE WHEN is_gland_face = 1 THEN 1 ELSE 0 END) as glandFace
FROM test_result 
WHERE user_id = #{userId}

    AND DATE(test_time) >= #{startDate}


    AND DATE(test_time) <= #{endDate}

GROUP BY DATE(test_time)
ORDER BY date

SELECT level as level, COUNT(*) as count FROM test_result WHERE user_id = #{userId} AND level IS NOT NULL AND level != ''
AND DATE(test_time) >= #{startDate}
AND DATE(test_time) <= #{endDate}
GROUP BY level ORDER BY count DESC

SELECT DATE(test_time) as date, COUNT(*) as total, SUM(CASE WHEN is_gland_face = 1 THEN 1 ELSE 0 END) as glandFace, SUM(CASE WHEN is_gland_face = 0 THEN 1 ELSE 0 END) as nonGlandFace, SUM(CASE WHEN level = '轻度' OR level = '轻微' THEN 1 ELSE 0 END) as light, SUM(CASE WHEN level = '中度' OR level = '中等' THEN 1 ELSE 0 END) as moderate, SUM(CASE WHEN level = '重度' OR level = '严重' THEN 1 ELSE 0 END) as severe FROM test_result WHERE user_id = #{userId}
AND DATE(test_time) >= #{startDate}
AND DATE(test_time) <= #{endDate}
GROUP BY DATE(test_time) ORDER BY date
